import java.io.*;
import java.math.*;
import java.util.*;
import java.util.stream.*;

public class E {

    private static final FastReader in = new FastReader();
    private static final FastWriter out = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        int t = 1;
        while (t-- > 0) {
            solve();
        }
        out.flush();
    }

    private void solve() {
        int n = in.nextInt();
        long kt = in.nextLong();

        if (kt >= n) {
            out.println(0);
            return;
        }

        int k = (int) kt;
        Modulo mod = new Modulo(998244353);
        long[] facts = mod.factorials(n);

        long ans = 0L;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long comb = mod.combination(c, i, facts);
            long power = mod.pow(c - i, n);
            long term = mod.times(comb, power);
            ans = ((i & 1) == 0) ? mod.plus(ans, term) : mod.minus(ans, term);
        }
        ans = mod.times(ans, mod.combination(n, n - k, facts));

        if (k > 0) ans = mod.times(ans, 2);
        out.println(ans);
    }
}

class FastReader {
    private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private static StringTokenizer tokenizer;

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public BigDecimal nextBigDecimal() { return new BigDecimal(next()); }
    public BigInteger nextBigInteger() { return new BigInteger(next()); }
    public boolean nextBoolean() { return Boolean.parseBoolean(next()); }
    public byte nextByte() { return Byte.parseByte(next()); }
    public double nextDouble() { return Double.parseDouble(next()); }
    public double[] nextDoubleArray(int len) {
        double[] arr = new double[len];
        for (int i = 0; i < len; i++) arr[i] = nextDouble();
        return arr;
    }
    public int nextInt() { return Integer.parseInt(next()); }
    public int[] nextIntArray(int len) {
        int[] arr = new int[len];
        for (int i = 0; i < len; i++) arr[i] = nextInt();
        return arr;
    }
    public long nextLong() { return Long.parseLong(next()); }
    public long[] nextLongArray(int len) {
        long[] arr = new long[len];
        for (int i = 0; i < len; i++) arr[i] = nextLong();
        return arr;
    }
}

class FastWriter extends PrintWriter {
    public FastWriter() { super(System.out); }

    public void println(boolean[] a) { printArray(a); }
    public void println(double[] a) { printArray(a); }
    public void println(int[] a) { printArray(a); }
    public void println(long[] a) { printArray(a); }
    public void println(Object... a) { printArray(a); }

    private <T> void printArray(T[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
        }
    }

    public <T> void println(List<T> l) { println(l.toArray()); }

    public void debug(String name, Object o) {
        String value = Arrays.deepToString(new Object[] { o });
        value = value.substring(1, value.length() - 1);
        System.err.println(name + " => " + value);
    }
}

class MathUtils {
    public static final double EPS = 1e-12;
    public static final Comparator<Double> EPS_COMPARATOR = (x, y) -> {
        if (x + EPS < y) return -1;
        else if (x - EPS > y) return 1;
        else return 0;
    };
    public static int compare(double x, double y) { return EPS_COMPARATOR.compare(x, y); }

    public static int binarySearch(int left, int right, IntPredicate leftShouldAdvance) {
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (leftShouldAdvance.test(mid)) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    public static int lowerBound(int[] a, int x) {
        return binarySearch(0, a.length, mid -> a[mid] < x);
    }
    public static int lowerBound(long[] a, long x) {
        return binarySearch(0, a.length, mid -> a[mid] < x);
    }
    public static int upperBound(int[] a, int x) {
        return binarySearch(0, a.length, mid -> a[mid] <= x);
    }
    public static int upperBound(long[] a, long x) {
        return binarySearch(0, a.length, mid -> a[mid] <= x);
    }

    public static int ternarySearchMaxInt(int left, int right, IntUnaryOperator f) {
        return binarySearch(left, right, mid -> f.applyAsInt(mid) < f.applyAsInt(Math.min(mid + 1, right - 1)));
    }
    public static int ternarySearchMaxLong(int left, int right, IntToLongFunction f) {
        return binarySearch(left, right, mid -> f.applyAsLong(mid) < f.applyAsLong(Math.min(mid + 1, right - 1)));
    }

    public static long gcd(long a, long b) {
        while (b > 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static long extendedEuclidean(long a, long b, long[] xy) {
        if (b == 0L) {
            xy[0] = 1L;
            xy[1] = 0L;
            return a;
        }
        long r = extendedEuclidean(b, a % b, xy);
        long t = xy[0];
        xy[0] = xy[1];
        xy[1] = t - a / b * xy[1];
        return r;
    }

    public static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

class Modulo {
    private final long mod;

    public Modulo(long mod) { this.mod = mod; }

    public long plus(long a, long b) {
        long c = a + b;
        if (c >= mod) c -= mod;
        return c;
    }

    public long minus(long a, long b) {
        long c = a - b;
        if (c < 0) c += mod;
        return c;
    }

    public long times(long a, long b) { return a * b % mod; }

    public long div(long a, long b) { return times(a, pow(b, mod - 2)); }

    public long pow(long a, long b) {
        long c = 1;
        while (b > 0) {
            if ((b & 1) > 0) c = c * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return c;
    }

    public long combination(int n, int k) {
        return div(factorial(n), times(factorial(k), factorial(n - k)));
    }

    public long combination(int n, int k, long[] factorials) {
        return div(factorials[n], times(factorials[k], factorials[n - k]));
    }

    public long factorial(int n) {
        long f = 1L;
        for (int i = 1; i <= n; i++) f = f * i % mod;
        return f;
    }

    public long[] factorials(int n) {
        long[] f = new long[n + 1];
        f[0] = 1L;
        for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % mod;
        return f;
    }
}
